input.command:
IMPLEMENT_TMPDIR="<TMPDIR>"
cat "$IMPLEMENT_TMPDIR/round-1/oos.md" 2>/dev/null | head -30 || echo "no oos.md"
echo "==="
cat "$IMPLEMENT_TMPDIR/round-1/aggregator-output.txt.events.jsonl" 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    try:
        ev = json.loads(line)
        if ev.get('type') in ('text', 'content_block_delta'):
            delta = ev.get('delta', {})
            if delta.get('type') == 'text_delta':
                print(delta.get('text', ''), end='')
        elif ev.get('type') == 'content_block_start':
            cb = ev.get('content_block', {})
            if cb.get('type') == 'text':
                print(cb.get('text', ''), end='')
    except:
        pass
" 2>/dev/null | tail -80 || echo "no events"
